                    "sql": "CREATE or replace TABLE izf-wh.maplemonk.shipment_status_mapping ( SHIPPING_STATUS string(16777216), Mapped_Status string(16777216) ); Insert INTO izf-wh.maplemonk.shipment_status_mapping values (\'DELIVERED\',\'Delivered\'),(\'CANCELLED\',\'Cancelled\'),(\'DELIVERED TO ORIGIN\',\'Returned\'),(\'SHIPMENT CREATED\',\'Shipment Created\'),(\'RETURNED\',\'Returned\'),(\'IN TRANSIT\',\'In Transit\'),(\'DELIVERY DELAYED\',\'In Transit\'),(\'DELIVERED TO ORIGIN\',\'RTO\'),(\'CONFIRMED\',\'Open\'),(\'IN_TRANSIT\',\'In Transit\'),(\'RTO DELIVERED\',\'RTO\'),(\'CANCELED\',\'Cancelled\'),(\'RTO IN TRANSIT\',\'RTO\'),(\'REACHED AT DESTINATION HUB\',\'In Transit\'),(\'PICKED UP\',\'In Transit\'),(\'UNDELIVERED-2ND ATTEMPT\',\'In Transit\'),(\'RTO_OFD\',\'RTO\'),(\'OUT FOR DELIVERY\',\'Out for delivery\'),(\'RTO INITIATED\',\'RTO\'),(\'PICKUP EXCEPTION\',\'Pickup Error\'),(\'CANCELLATION REQUESTED\',\'Pickup Error\'),(\'READY TO SHIP\',\'Ready to Ship\'),(\'OUT_FOR_DELIVERY\',\'Out for delivery\'),(\'SHIPPED\',\'In Transit\'),(\'PICKUP RESCHEDULED\',\'Pickup Error\'),(\'UNDELIVERED-3RD ATTEMPT\',\'In Transit\'),(\'MISROUTED\',\'Misrouted\'),(\'PICKUP SCHEDULED\',\'Pickup Error\'),(\'UNDELIVERED-1ST ATTEMPT\',\'In Transit\'),(\'Not Traceble\',\'Pickup Error\'),(\'UNDELIVERED\',\'In Transit\'),(\'LOST\',\'Lost\'),(\'IN TRANSIT-EN-ROUTE\',\'In Transit\'),(\'Indian Speed Post\',\'Indian Speed Post\'),(\'Exception\',\'Exception\'),(\'Shipment Booked\',\'Pickup Error\'),(\'Assigned\',\'Assigned\'),(\'Pending\',\'Pending\'),(\'PrINT\',\'PrINT\'),(\'IN TRANSIT-AT DESTINATION HUB\',\'In Transit\'),(\'Upcoming\',\'Order Yet To sync\'),(\'RTO-In Transit\',\'RTO\'),(\'PICKUP ERROR\',\'Pickup Error\'),(\'RTO-Out for Delivery\',\'RTO\'),(\'RTO-Delivered\',\'RTO\'),(\'OUT FOR PICKUP\',\'Pickup Error\'),(\'RTO_NDR\',\'RTO\'),(\'RTO-Exception\',\'Exception\'),(\'Delayed\',\'In Transit\'),(\'IN TRANSIT-AT SOURCE HUB\',\'In Transit\'),(\'RTS\',\'Underprocess\'),(\'Manifested\',\'Pickup Error\'),(\'Dispatched\',\'In Transit\'),(\'RTO\',\'RTO\'),(\'Not Picked\',\'Pickup Error\'),(\'DAMAGED\',\'Damaged\'),(\'Closed\',\'Cancelled\'),(\'Open\',\'Open\'),(\'On Hold\',\'On Hold\'),(\'Shipped - Returned to Seller\',\'RTO\'),(\'Shipped - Delivered to Buyer\',\'Delivered\'),(\'Shipped - Picked Up\',\'In Transit\'),(\'Shipped - Rejected by Buyer\',\'RTO\'),(\'Shopify_Processed\',\'Shopify_Processed\'),(\'Ready to dispatch\',\'Ready to Dispatch\'),(\'RTO Undelivered\',\'RTO\'),(\'Shipment Lost\',\'Lost\'),(\'Shipment Error\',\'Shipment Error\'),(\'RTO In-Transit\',\'RTO\'),(\'Dispatch / RTO\',\'RTO\'),(\'Pending Pick-up\',\'Pending\'),(\'Dispatch/Intransit\',\'In Transit\'),(\'Dispatch /Lost and Damange\',\'Lost\'),(\'Dispatch /Undelivered\',\'Undelivered\'),(\'Non serviceable\',\'Non Serviceable\'),(\'Not serviceable\',\'Non Serviceable\'),(\'Dispatch/Delivered\',\'Delivered\'),(\'Refund\',\'Refund\'),(\'F&P\',\'F&P\'),(\'SHIPPED - RETURNING TO SELLER\',\'RTO\'),(\'SHIPPED - LOST IN TRANSIT\',\'Lost\'),(\'SHIPPED - DAMAGED\',\'Damaged\'),(\'SHIPPED - OUT FOR DELIVERY\',\'Out for delivery\'); create table if not exists izf-wh.maplemonk.facility_pincode( facility string, pincode string ); CREATE OR REPLACE TABLE izf-wh.maplemonk.marketplace_mapping ( marketplace STRING, final_marketplace STRING ); INSERT INTO izf-wh.maplemonk.marketplace_mapping (marketplace, final_marketplace) VALUES (\'FLIPKART_UNITO\', \'Flipkart\'), (\'LIMEROAD\', \'Limeroad\'), (\'MYNTRAPPMP\', \'Myntra\'), (\'PERSONAL\', \'Personal\'), (\'SHOPIFY\', \'Website\'), (\'AMAZON_IZF\', \'Amazon\'), (\'POPCLUB\', \'Popclub\'), (\'NYKAA_FASHION\', \'Nykaa\'), (\'CUSTOM\', \'Custom\'), (\'AJIO_OMNI\', \'Ajio\'), (\'NYKAA_COM\', \'Nykaa\'), (\'STUMBL\', \'Stumbl\'), (\'BEWAKOOF\', \'Bewakoof\'), (\'FLIPKART\', \'Flipkart\'), (\'OFFLINE\', \'Offline\'), (\'AMAZON.IN\', \'Amazon\'), (\'WEBSITE\',\'Website\'); create or replace table izf-wh.maplemonk.IZF_sales_consolidated_intermediate as select b.customer_id ,upper(b.SHOP_NAME) SHOP_NAME ,upper(b.marketplace) as marketplace ,Upper(b.FINAL_UTM_CHANNEL) AS CHANNEL ,Upper(coalesce(b.source_name,b.FINAL_UTM_SOURCE)) AS SOURCE ,b.ORDER_ID ,order_name reference_code ,b.PHONE ,b.NAME ,b.EMAIL ,coalesce(cast(b.shipping_status_update_date as timestamp),cast(c.shipping_last_update_date as timestamp)) AS SHIPPING_LAST_UPDATE_DATE ,b.SKU ,b.PRODUCT_ID ,Upper(b.PRODUCT_NAME) PRODUCT_NAME ,b.CURRENCY ,Upper(b.CITY) As CITY ,Upper(b.STATE) AS State ,Upper(b.ORDER_STATUS) ORDER_STATUS ,cast(TIMESTAMP(b.ORDER_TIMESTAMP) as date) AS Order_Date ,cast(TIMESTAMP(b.ORDER_TIMESTAMP) as datetime) AS Order_Time ,b.QUANTITY ,b.GROSS_SALES_BEFORE_TAX AS GROSS_SALES_BEFORE_TAX ,b.DISCOUNT_BEFORE_TAX AS DISCOUNT ,b.TAX ,b.SHIPPING_PRICE ,b.TOTAL_SALES AS SELLING_PRICE ,UPPER(c.order_status) as OMS_order_status ,UPPER(coalesce(b.shipping_status, c.shipping_status)) AS SHIPPING_STATUS ,upper(coalesce(shipmap.final_shipping_status,b.shipping_status, c.shipping_status)) FINAL_SHIPPING_STATUS ,cast(b.LINE_ITEM_ID as string) as SALEORDERITEMCODE ,c.suborder_id as SALES_ORDER_ITEM_ID ,coalesce(b.awb,c.awb) AWB ,UPPER(REPLACE(IF(ARRAY_LENGTH(GATEWAY) > 0, GATEWAY[OFFSET(0)],\'NA\'), \'\"\', \'\')) PAYMENT_GATEWAY ,upper(c.payment_mode) Payment_Mode ,Upper(coalesce(c.Courier,b.courier)) AS COURIER ,coalesce(cast(timestamp(b.Shipping_created_at) as date),cast(timestamp(c.manifest_date) as date)) AS DISPATCH_DATE ,coalesce(cast(timestamp(c.delivered_date) as date),case when b.shipping_status like \'delivered\' then cast(timestamp(b.shipping_status_update_date) as date) end) AS DELIVERED_DATE ,case when lower(coalesce(shipmap.final_shipping_status,b.shipping_status, c.shipping_status)) = \'delivered\' then 1 else 0 end AS DELIVERED_STATUS ,coalesce(case when b.IS_REFUND=1 and lower(b.order_status) not in (\'cancelled\') then 1 end,c.IS_REFUND) AS RETURN_FLAG ,case when coalesce(case when b.IS_REFUND=1 and lower(b.order_status) not in (\'cancelled\') then 1 end,c.IS_REFUND) = 1 and lower(b.order_status) not in (\'cancelled\') then ifnull(refund_quantity,0) end returned_quantity ,case when coalesce(case when b.IS_REFUND=1 and lower(b.order_status) not in (\'cancelled\') then 1 end,c.IS_REFUND) = 1 and lower(b.order_status) not in (\'cancelled\') then ifnull(refund_value,0) end returned_sales ,case when lower(b.order_status) in (\'cancelled\') then cast(quantity as INT64) end cancelled_quantity ,b.shopify_new_customer_flag as NEW_CUSTOMER_FLAG ,Upper(b.shopify_acquisition_product) as acquisition_product ,cast(case when lower(coalesce(shipmap.final_shipping_status,b.shipping_status, c.shipping_status)) in (\'delivered\',\'delivered to origin\') then date_diff(date(b.ORDER_TIMESTAMP),date(coalesce(cast(b.shipping_status_update_date as timestamp),cast(c.shipping_last_update_date as timestamp))),day) when lower(coalesce(shipmap.final_shipping_status,b.shipping_status, c.shipping_status)) in (\'in transit\', \'shipment created\') then date_diff(date(b.ORDER_TIMESTAMP), CURRENT_DATE(),day) end as INT64) as Days_in_Shipment ,b.shopify_acquisition_date AS MARKETPLACE_ACQUISITION_DATE ,b.SKU_CODE ,UPPER(b.PRODUCT_NAME_FINAL) PRODUCT_NAME_FINAL ,UPPER(coalesce(c.category,b.PRODUCT_CATEGORY)) PRODUCT_CATEGORY ,upper(b.PRODUCT_SUB_CATEGORY) PRODUCT_SUB_CATEGORY ,b.SKU_CODE commonsku ,upper(c.warehouse_name) WAREHOUSE ,coalesce(b.pincode,c.pincode) as pincode ,coalesce(c.pickup_pincode,fa.pincode) as source_pincode ,b.discount_codes ,case when upper(b.sku) like \'B%\' then \'BASICS\' else \'IZF\' end as brand from izf-wh.maplemonk.IZF_SHOPIFY_FACT_ITEMS b left join (select * from ( select * ,row_number()over(partition by reference_code, Marketplace_LineItem_ID order by last_update_date desc) rw from izf-wh.maplemonk.IZF_EasyEcom_FACT_ITEMS ) z where z.rw = 1 and lower(marketplace) like any (\'%shopify%\') ) c on replace(b.order_name,\'#\',\'\') = c.reference_code and b.LINE_ITEM_ID=c.Marketplace_LineItem_ID left join (select * from (select * , row_number() over (partition by lower(facility) order by 1) rw from izf-wh.maplemonk.facility_pincode ) where rw = 1 ) fa on lower(c.warehouse_name) = lower(fa.facility) left join ( select * from ( select upper(Shipping_status) shipping_status ,upper(mapped_status) final_shipping_status ,row_number() over (partition by lower(shipping_Status) order by 1) rw from izf-wh.maplemonk.shipment_status_mapping ) where rw = 1 ) ShipMap on lower(coalesce(b.shipping_status,c.shipping_status,b.ORDER_STATUS)) = lower(ShipMap.shipping_status) UNION ALL SELECT NULL AS customer_id ,UPPER(SHOP_NAME) AS SHOP_NAME ,UPPER(marketplace) AS marketplace ,UPPER(marketplace) AS CHANNEL ,UPPER(marketplace) AS SOURCE ,ORDER_ID ,reference_code ,contact_num AS PHONE ,customer_name AS NAME ,email AS EMAIL ,cast(shipping_last_update_date as timestamp) AS SHIPPING_LAST_UPDATE_DATE ,master_SKU as sku ,PRODUCT_ID ,UPPER(PRODUCTNAME) AS PRODUCT_NAME ,CURRENCY ,UPPER(CITY) AS City ,UPPER(STATE) AS State ,UPPER(ORDER_STATUS) AS Order_Status ,cast(cast(ORDER_DATE as datetime) as date) AS Order_Date ,CAST(ORDER_DATE AS datetime) AS ORDER_TIMESTAMP ,SUBORDER_QUANTITY AS QUANTITY ,IFNULL(SELLING_PRICE, 0) - IFNULL(tax, 0) + IFNULL(DISCOUNT, 0) AS GROSS_SALES_BEFORE_TAX ,DISCOUNT AS DISCOUNT ,TAX ,SHIPPING_PRICE ,SELLING_PRICE AS SELLING_PRICE ,UPPER(ORDER_STATUS) AS OMS_Order_Status ,UPPER(b.Shipping_status) AS SHIPPING_STATUS ,UPPER(COALESCE(shipmap.final_shipping_status, b.shipping_status)) AS FINAL_SHIPPING_STATUS ,Marketplace_LineItem_ID AS SALEORDERITEMCODE ,suborder_id AS SALES_ORDER_ITEM_ID ,AWB ,NULL AS Payment_Gateway ,payment_mode AS Payment_Mode ,UPPER(COURIER) AS COURIER ,MANIFEST_DATE AS DISPATCH_DATE ,DELIVERED_DATE ,CASE WHEN LOWER(COALESCE(ShipMap.shipping_status, b.shipping_status)) = \'delivered\' THEN 1 ELSE 0 END AS DELIVERED_STATUS ,IS_REFUND AS RETURN_FLAG ,CASE WHEN is_refund = 1 THEN CAST(suborder_quantity AS INT64) END AS returned_quantity ,CASE WHEN is_refund = 1 AND LOWER(order_status) NOT IN (\'cancelled\') THEN IFNULL(is_refund, 0) END AS returned_sales ,CASE WHEN is_refund = 0 AND LOWER(order_status) IN (\'cancelled\') THEN CAST(suborder_quantity AS INT64) END AS cancelled_quantity ,CAST(new_customer_flag AS STRING) AS NEW_CUSTOMER_FLAG ,NULL AS ACQUISITION_PRODUCT ,cast(Days_in_shipment as INT64) AS DAYS_IN_SHIPMENT ,NULL AS ACQUISITION_DATE ,SKU AS SKU_CODE ,UPPER(mapped_product_name) AS PRODUCT_NAME_FINAL ,UPPER(mapped_category) AS PRODUCT_CATEGORY ,null AS PRODUCT_SUB_CATEGORY ,b.commonsku ,UPPER(WAREHOUSE_NAME) AS WAREHOUSE ,pincode ,pickup_pincode ,null as discount_codes ,case when upper(b.master_SKU) like \'B%\' then \'BASICS\' else \'IZF\' end as brand FROM izf-wh.maplemonk.IZF_EasyEcom_FACT_ITEMS b LEFT JOIN ( SELECT * FROM ( SELECT UPPER(Shipping_status) AS shipping_status, UPPER(mapped_status) AS final_shipping_status, ROW_NUMBER() OVER (PARTITION BY LOWER(shipping_Status) ORDER BY 1) AS rw FROM izf-wh.maplemonk.shipment_status_mapping ) shipmap WHERE shipmap.rw = 1 ) ShipMap ON LOWER(COALESCE(b.shipping_status, b.order_status)) = LOWER(ShipMap.shipping_status) WHERE not(LOWER(marketplace) LIKE \'%shopify%\' or LOWER(marketplace) LIKE ANY (\'%amazon%\', \'%gofynd\') or LOWER(marketplace) LIKE \'%b2b%\') UNION ALL SELECT NULL AS customer_id ,\'KNOT\' AS SHOP_NAME ,\'KNOT\' AS marketplace ,\'KNOT\' AS CHANNEL ,\'KNOT\' AS SOURCE ,concat(sku,colour,order_date,selling_price) ORDER_ID ,concat(sku,colour,order_date,selling_price) reference_code ,NULL AS PHONE ,cast(NULL as string) AS NAME ,cast(NULL as string) AS EMAIL ,cast(order_date as timestamp) AS SHIPPING_LAST_UPDATE_DATE ,sku ,cast(NULL as string) AS PRODUCT_ID ,UPPER(PRODUCT_NAME) AS PRODUCT_NAME ,\'INR\' as CURRENCY ,cast(NULL as string) AS City ,cast(NULL as string) AS State ,\'DELIVERED\' AS Order_Status ,cast(cast(ORDER_DATE as datetime) as date) AS Order_Date ,CAST(ORDER_DATE AS datetime) AS ORDER_TIMESTAMP ,QUANTITY AS QUANTITY ,IFNULL(SELLING_PRICE, 0) AS GROSS_SALES_BEFORE_TAX ,NULL AS DISCOUNT ,NULL AS TAX ,NULL AS SHIPPING_PRICE ,SELLING_PRICE AS SELLING_PRICE ,\'DELIVERED\' AS OMS_Order_Status ,\'DELIVERED\' AS SHIPPING_STATUS ,\'DELIVERED\' AS FINAL_SHIPPING_STATUS ,concat(sku,colour,order_date,selling_price) AS SALEORDERITEMCODE ,concat(sku,colour,order_date,selling_price) AS SALES_ORDER_ITEM_ID ,cast(NULL as string) AS AWB ,NULL AS Payment_Gateway ,cast(NULL as string) AS Payment_Mode ,cast(NULL as string) AS COURIER ,CAST(ORDER_DATE AS datetime) AS DISPATCH_DATE ,CAST(ORDER_DATE AS datetime) AS DELIVERED_DATE ,1 AS DELIVERED_STATUS ,0 AS RETURN_FLAG ,0 AS returned_quantity ,0 AS returned_sales ,0 AS cancelled_quantity ,CAST(null AS STRING) AS NEW_CUSTOMER_FLAG ,NULL AS ACQUISITION_PRODUCT ,0 AS DAYS_IN_SHIPMENT ,NULL AS ACQUISITION_DATE ,SKU AS SKU_CODE ,UPPER(product_name) AS PRODUCT_NAME_FINAL ,UPPER(product_category) AS PRODUCT_CATEGORY ,null AS PRODUCT_SUB_CATEGORY ,sku as commonsku ,CAST(null AS string) AS WAREHOUSE ,CAST(null AS string) AS pincode ,CAST(null AS string) AS pickup_pincode ,null as discount_codes ,case when upper(sku) like \'B%\' then \'BASICS\' else \'IZF\' end as brand FROM izf-wh.maplemonk.izf_knot_fact_items UNION ALL SELECT NULL AS customer_id, \'NEON MARKET\' AS SHOP_NAME, \'NEON MARKET\' AS marketplace, \'NEON MARKET\' AS CHANNEL, \'NEON MARKET\' AS SOURCE, CONCAT(sku,order_date,selling_price) AS ORDER_ID, CONCAT(sku,order_date,selling_price) AS reference_code, NULL AS PHONE, CAST(NULL AS STRING) AS NAME, CAST(NULL AS STRING) AS EMAIL, CAST(NULL AS TIMESTAMP) AS SHIPPING_LAST_UPDATE_DATE, sku AS sku, CAST(NULL AS STRING) AS PRODUCT_ID, UPPER(Product_name) AS PRODUCT_NAME, \'INR\' AS CURRENCY, \'BENGALURU\' AS City, \'KARNATAKA\' AS State, \'DELIVERED\' AS Order_Status, CAST(order_date AS DATE) AS Order_Date, CAST(order_date AS DATETIME) AS ORDER_TIMESTAMP, quantity AS QUANTITY, IFNULL(gross_price, 0) AS GROSS_SALES_BEFORE_TAX, NULL AS DISCOUNT, NULL AS TAX, NULL AS SHIPPING_PRICE, selling_price AS SELLING_PRICE, \'DELIVERED\' AS OMS_Order_Status, \'DELIVERED\' AS SHIPPING_STATUS, \'DELIVERED\' AS FINAL_SHIPPING_STATUS, CONCAT(sku,order_date,selling_price,\'_\',quantity) AS SALEORDERITEMCODE, CONCAT(sku,order_date,selling_price,\'_\',quantity) AS SALES_ORDER_ITEM_ID, CAST(NULL AS STRING) AS AWB, NULL AS Payment_Gateway, CAST(NULL AS STRING) AS Payment_Mode, CAST(NULL AS STRING) AS COURIER, CAST(order_date AS DATETIME) AS DISPATCH_DATE, CAST(order_date AS DATETIME) AS DELIVERED_DATE, 1 AS DELIVERED_STATUS, 0 AS RETURN_FLAG, 0 AS returned_quantity, 0 AS returned_sales, 0 AS cancelled_quantity, CAST(NULL AS STRING) AS NEW_CUSTOMER_FLAG, NULL AS ACQUISITION_PRODUCT, 0 AS DAYS_IN_SHIPMENT, NULL AS ACQUISITION_DATE, NULL AS SKU_CODE, UPPER(product_name_final) AS PRODUCT_NAME_FINAL, UPPER(COALESCE(product_category, \'OTHER\')) AS PRODUCT_CATEGORY, NULL AS PRODUCT_SUB_CATEGORY, NULL AS commonsku, CAST(NULL AS STRING) AS WAREHOUSE, CAST(NULL AS STRING) AS pincode, CAST(NULL AS STRING) AS pickup_pincode, NULL AS discount_codes, case when upper(sku) like \'B%\' then \'BASICS\' else \'IZF\' end as brand FROM `izf-wh.maplemonk.izf_neon_market_fact_items` ; CREATE OR REPLACE TABLE izf-wh.maplemonk.Final_customerID AS WITH new_phone_numbers AS ( SELECT phone, contact_num, 19700000000 + ROW_NUMBER() OVER (ORDER BY contact_num ASC) AS maple_monk_id FROM ( SELECT DISTINCT RIGHT(REGEXP_REPLACE(phone, \'[^a-zA-Z0-9]+\', \'\'), 10) AS contact_num, phone FROM izf-wh.maplemonk.IZF_sales_consolidated_intermediate ) a ), INT AS ( SELECT contact_num, email, COALESCE(maple_monk_id, id2) AS maple_monk_id FROM ( SELECT contact_num, email, maple_monk_id, 19800000000 + ROW_NUMBER() OVER (PARTITION BY maple_monk_id IS NULL ORDER BY email ASC) AS id2 FROM ( SELECT DISTINCT COALESCE(p.contact_num, RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10)) AS contact_num, e.email, maple_monk_id FROM ( SELECT phone AS contact_num, email FROM izf-wh.maplemonk.IZF_sales_consolidated_intermediate ) e LEFT JOIN new_phone_numbers p ON p.contact_num = RIGHT(REGEXP_REPLACE(e.contact_num, \'[^a-zA-Z0-9]+\', \'\'), 10) ) a ) b ) SELECT contact_num, email, maple_monk_id FROM INT WHERE COALESCE(contact_num, email) IS NOT NULL; CREATE OR REPLACE TABLE izf-wh.maplemonk.IZF_sales_consolidated AS SELECT mm.final_marketplace, COALESCE(m.maple_monk_id_phone, d.maple_monk_id) AS customer_id_final, MIN(order_date) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS acquisition_date, MIN(CASE WHEN LOWER(order_status) NOT IN (\'cancelled\') THEN order_date END) OVER (PARTITION BY COALESCE(m.maple_monk_id_phone, d.maple_monk_id)) AS first_complete_order_date, sum(ifnull(quantity, 0)) over(partition by reference_code order by 1) Order_Quantity, split(replace(UPPER(trim(parts[SAFE_OFFSET(ARRAY_LENGTH(parts) - 1)])),\'_\',\'\'),\'/Z\')[SAFE_OFFSET(0)] as sku_size, replace(replace(parts[safe_offset(0)],\'`\',\'\'),\'\\'\',\'\') sku_style, CASE WHEN REGEXP_CONTAINS(UPPER(REPLACE(REPLACE(parts[SAFE_OFFSET(0)],\'`\',\'\'),\'\\'\',\'\')), r\'(MEN|M)\') THEN \'Men\' ELSE \'Women\' END AS gender, m.* FROM ( SELECT c.maple_monk_id AS maple_monk_id_phone, CASE WHEN REGEXP_CONTAINS(LOWER(o.product_category), r\'(sweatshirt|sweatshirts|hoodie|pullover)\') THEN \'Sweatshirts\' WHEN REGEXP_CONTAINS(LOWER(o.product_category), r\'(tshirt|t-shirt|top|tops|tube top)\') THEN \'Tshirts\' WHEN REGEXP_CONTAINS(LOWER(o.product_category), r\'(shrug|shrugs)\') THEN \'Shrug\' WHEN REGEXP_CONTAINS(LOWER(o.product_category), r\'(dress|dresses)\') THEN \'Dresses\' WHEN REGEXP_CONTAINS(LOWER(o.product_category), r\'(co-ord|co ord|coord)\') THEN \'Co-Ords\' WHEN REGEXP_CONTAINS(LOWER(o.product_category), r\'(jacket|jackets|blazer)\') THEN \'Jackets\' WHEN REGEXP_CONTAINS(LOWER(o.product_category), r\'(shirt|shirts)\') THEN \'Shirts\' WHEN REGEXP_CONTAINS(LOWER(o.product_category), r\'(short|shorts)\') THEN \'Shorts\' ELSE \'Others\' END AS article_type, ARRAY( SELECT part FROM UNNEST(SPLIT(replace(o.sku,\'_\',\'-\'), \'-\')) AS part WHERE part != \'\' ) as parts, o.* FROM izf-wh.maplemonk.IZF_sales_consolidated_intermediate o LEFT JOIN ( SELECT * FROM ( SELECT contact_num AS phone, maple_monk_id, ROW_NUMBER() OVER (PARTITION BY contact_num ORDER BY maple_monk_id ASC) AS magic FROM izf-wh.maplemonk.Final_customerID ) WHERE magic = 1 ) c ON c.phone = RIGHT(REGEXP_REPLACE(o.phone, \'[^a-zA-Z0-9]+\', \'\'), 10) ) m LEFT JOIN ( SELECT DISTINCT maple_monk_id, email FROM izf-wh.maplemonk.Final_customerID WHERE contact_num IS NULL ) d ON d.email = m.email LEFT JOIN izf-wh.maplemonk.marketplace_mapping mm ON lower(m.marketplace) = lower(mm.marketplace); ALTER TABLE izf-wh.maplemonk.IZF_sales_consolidated DROP COLUMN IF EXISTS new_customer_flag, DROP COLUMN IF EXISTS acquisition_product; ALTER TABLE izf-wh.maplemonk.IZF_sales_consolidated ADD COLUMN new_customer_flag STRING, ADD COLUMN new_customer_flag_month STRING, ADD COLUMN acquisition_product STRING, ADD COLUMN acquisition_channel STRING, ADD COLUMN acquisition_marketplace STRING; UPDATE izf-wh.maplemonk.IZF_sales_consolidated AS A SET A.new_customer_flag = B.flag FROM ( SELECT order_id, customer_id_final, Order_Date, CASE WHEN Order_Date = first_complete_order_date THEN \'New\' WHEN Order_Date < first_complete_order_date OR first_complete_order_date IS NULL THEN \'Yet to make completed order\' WHEN Order_Date > first_complete_order_date THEN \'Repeat\' END AS Flag, row_number() over (partition by order_id, customer_id_final order by order_date) rw FROM izf-wh.maplemonk.IZF_sales_consolidated ) AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final and rw =1; UPDATE izf-wh.maplemonk.IZF_sales_consolidated SET new_customer_flag = CASE WHEN new_customer_flag IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' WHEN new_customer_flag IS NULL AND LOWER(order_status) IN (\'cancelled\') THEN \'Yet to make completed order\' ELSE new_customer_flag END WHERE new_customer_flag IS NULL; UPDATE izf-wh.maplemonk.IZF_sales_consolidated AS A SET A.new_customer_flag_month = B.flag FROM ( SELECT DISTINCT order_id, customer_id_final, order_date, CASE WHEN DATE_TRUNC(order_date, MONTH) = DATE_TRUNC(first_complete_order_date, MONTH) THEN \'New\' WHEN DATE_TRUNC(order_date, MONTH) < DATE_TRUNC(first_complete_order_date, MONTH) OR acquisition_date IS NULL THEN \'Yet to make completed order\' WHEN DATE_TRUNC(order_date, MONTH) > DATE_TRUNC(first_complete_order_date, MONTH) THEN \'Repeat\' END AS flag, row_number() over (partition by order_id, customer_id_final order by order_date) rw FROM izf-wh.maplemonk.IZF_sales_consolidated ) AS B WHERE A.order_id = B.order_id AND A.customer_id_final = B.customer_id_final and rw=1; UPDATE izf-wh.maplemonk.IZF_sales_consolidated SET new_customer_flag_month = CASE WHEN new_customer_flag_month IS NULL AND (LOWER(order_status) IS NULL OR LOWER(order_status) NOT IN (\'cancelled\')) THEN \'New\' ELSE new_customer_flag_month END WHERE new_customer_flag_month IS NULL; CREATE OR REPLACE TEMPORARY TABLE temp_source_1 AS SELECT customer_id_final, source AS channel, shop_name AS marketplace FROM (SELECT * FROM( SELECT customer_id_final, order_date, source, shop_name, MIN(CASE WHEN LOWER(order_status) <> \'cancelled\' THEN order_date END) OVER (PARTITION BY customer_id_final) AS firstOrderDate, row_number() over (partition by customer_id_final order by ORDER_TIME) rw FROM izf-wh.maplemonk.IZF_sales_consolidated ) AS res where rw =1 ) WHERE order_date = firstOrderDate; UPDATE izf-wh.maplemonk.IZF_sales_consolidated AS a SET a.acquisition_channel = b.channel FROM temp_source_1 AS b WHERE a.customer_id_final = b.customer_id_final; UPDATE izf-wh.maplemonk.IZF_sales_consolidated AS a SET a.acquisition_marketplace = b.marketplace FROM temp_source_1 AS b WHERE a.customer_id_final = b.customer_id_final; CREATE OR replace temporary TABLE temp_product_1 AS SELECT customer_id_final, product_name_final FROM ( SELECT customer_id_final, order_date, product_name_final, SELLING_PRICE , Min(case when lower(order_status) <> \'cancelled\' then order_date end) OVER (partition BY customer_id_final) firstOrderdate, row_number() over (partition by customer_id_final order by ORDER_TIME asc, selling_price desc) rw FROM izf-wh.maplemonk.IZF_sales_consolidated )res WHERE order_date=firstorderdate and rw=1; UPDATE izf-wh.maplemonk.IZF_sales_consolidated AS A SET A.acquisition_product = B.product_name_final FROM ( SELECT * FROM temp_product_1 ) AS B WHERE A.customer_id_final = B.customer_id_final; UPDATE izf-wh.maplemonk.IZF_sales_consolidated SET state = CASE WHEN UPPER(state) IN (\'AP\', \'ANDHRA PRADESH\') THEN \'ANDHRA PRADESH\' WHEN UPPER(state) IN (\'AR\', \'ARUNACHAL PRADESH\') THEN \'ARUNACHAL PRADESH\' WHEN UPPER(state) IN (\'AS\', \'ASSAM\') THEN \'ASSAM\' WHEN UPPER(state) IN (\'BR\', \'BIHAR\') THEN \'BIHAR\' WHEN UPPER(state) IN (\'CT\', \'CHHATTISGARH\') THEN \'CHHATTISGARH\' WHEN UPPER(state) IN (\'GA\', \'GOA\') THEN \'GOA\' WHEN UPPER(state) IN (\'GJ\', \'GUJARAT\') THEN \'GUJARAT\' WHEN UPPER(state) IN (\'HR\', \'HARYANA\') THEN \'HARYANA\' WHEN UPPER(state) IN (\'HP\', \'HIMACHAL PRADESH\') THEN \'HIMACHAL PRADESH\' WHEN UPPER(state) IN (\'JH\', \'JHARKHAND\') THEN \'JHARKHAND\' WHEN UPPER(state) IN (\'KA\', \'KARNATAKA\') THEN \'KARNATAKA\' WHEN UPPER(state) IN (\'KL\', \'KERALA\') THEN \'KERALA\' WHEN UPPER(state) IN (\'MP\', \'MADHYA PRADESH\') THEN \'MADHYA PRADESH\' WHEN UPPER(state) IN (\'MH\', \'MAHARASHTRA\') THEN \'MAHARASHTRA\' WHEN UPPER(state) IN (\'MN\', \'MANIPUR\') THEN \'MANIPUR\' WHEN UPPER(state) IN (\'ML\', \'MEGHALAYA\') THEN \'MEGHALAYA\' WHEN UPPER(state) IN (\'MZ\', \'MIZORAM\') THEN \'MIZORAM\' WHEN UPPER(state) IN (\'NL\', \'NAGALAND\') THEN \'NAGALAND\' WHEN UPPER(state) IN (\'OR\', \'ODISHA\') THEN \'ODISHA\' WHEN UPPER(state) IN (\'PB\', \'PUNJAB\') THEN \'PUNJAB\' WHEN UPPER(state) IN (\'RJ\', \'RAJASTHAN\') THEN \'RAJASTHAN\' WHEN UPPER(state) IN (\'SK\', \'SIKKIM\') THEN \'SIKKIM\' WHEN UPPER(state) IN (\'TN\', \'TAMIL NADU\') THEN \'TAMIL NADU\' WHEN UPPER(state) IN (\'TS\', \'TL\', \'TELANGANA\') THEN \'TELANGANA\' WHEN UPPER(state) IN (\'TR\', \'TRIPURA\') THEN \'TRIPURA\' WHEN UPPER(state) IN (\'UP\', \'UTTAR PRADESH\') THEN \'UTTAR PRADESH\' WHEN UPPER(state) IN (\'UT\', \'UK\', \'UTTARAKHAND\') THEN \'UTTARAKHAND\' WHEN UPPER(state) IN (\'WB\', \'WEST BENGAL\') THEN \'WEST BENGAL\' WHEN UPPER(state) IN (\'AN\', \'ANDAMAN AND NICOBAR ISLANDS\', \'ANDAMAN & NICOBAR ISLANDS\') THEN \'ANDAMAN AND NICOBAR ISLANDS\' WHEN UPPER(state) IN (\'CH\', \'CHANDIGARH\') THEN \'CHANDIGARH\' WHEN UPPER(state) IN (\'DN\', \'DADRA AND NAGAR HAVELI\') THEN \'DADRA AND NAGAR HAVELI\' WHEN UPPER(state) IN (\'DD\', \'DAMAN AND DIU\') THEN \'DAMAN AND DIU\' WHEN UPPER(state) IN (\'LD\', \'LAKSHADWEEP\') THEN \'LAKSHADWEEP\' WHEN UPPER(state) IN (\'DL\', \'DELHI\') THEN \'DELHI\' WHEN UPPER(state) IN (\'PY\', \'PUDUCHERRY\') THEN \'PUDUCHERRY\' WHEN UPPER(state) IN (\'JK\', \'JAMMU AND KASHMIR\', \'JAMMU & KASHMIR\') THEN \'JAMMU AND KASHMIR\' WHEN UPPER(state) = \'LADAKH\' THEN \'LADAKH\' ELSE state END WHERE UPPER(state) IN ( \'AP\', \'AR\', \'AS\', \'BR\', \'CT\', \'GA\', \'GJ\', \'HR\', \'HP\', \'JH\', \'KA\', \'KL\', \'MP\', \'MH\', \'MN\', \'ML\', \'MZ\', \'NL\', \'OR\', \'PB\', \'RJ\', \'SK\', \'TN\', \'TS\', \'TL\', \'TR\', \'UP\', \'UT\', \'UK\', \'WB\', \'AN\', \'CH\', \'DN\', \'DD\', \'LD\', \'DL\', \'PY\', \'JK\', \'JAMMU & KASHMIR\', \'ANDAMAN & NICOBAR ISLANDS\' ); CREATE OR REPLACE TABLE maplemonk.izf_sales_trend_analysis AS WITH daily_sales AS ( SELECT DATE(s.order_date) AS order_date, COUNT(DISTINCT order_id) AS Daily_Total_Orders, SUM(IFNULL(quantity, 0)) AS Daily_Total_Order_Quantity, SUM(IFNULL(selling_price, 0)) AS Daily_Total_Sales FROM maplemonk.izf_sales_consolidated s GROUP BY 1 ), weekly_summary AS ( SELECT DATE_TRUNC(order_date, WEEK(MONDAY)) AS week_start_date, DATE_TRUNC(DATE_TRUNC(order_date, WEEK(MONDAY)), MONTH) AS month_start_date, DATE_TRUNC(DATE_TRUNC(order_date, WEEK(MONDAY)), YEAR) AS year_start_date, SUM(Daily_Total_Orders) AS Weekly_Total_Orders, SUM(Daily_Total_Order_Quantity) AS Weekly_Total_Order_Quantity, SUM(Daily_Total_Sales) AS Weekly_Total_Sales FROM daily_sales GROUP BY 1, 2, 3 ), monthly_aggregates AS ( SELECT DATE_TRUNC(order_date, MONTH) AS month_start_date, SUM(Daily_Total_Orders) AS Monthly_Total_Orders, SUM(Daily_Total_Order_Quantity) AS Monthly_Total_Order_Quantity, SUM(Daily_Total_Sales) AS Monthly_Total_Sales FROM daily_sales GROUP BY 1 ), yearly_aggregates AS ( SELECT DATE_TRUNC(order_date, YEAR) AS year_start_date, SUM(Daily_Total_Orders) AS Yearly_Total_Orders, SUM(Daily_Total_Order_Quantity) AS Yearly_Total_Order_Quantity, SUM(Daily_Total_Sales) AS Yearly_Total_Sales FROM daily_sales GROUP BY 1 ) SELECT ws.week_start_date AS week, ws.month_start_date AS month, ws.Weekly_Total_Orders AS Total_Orders, ws.Weekly_Total_Order_Quantity AS Total_Order_Quantity_Weekly, ws.Weekly_Total_Sales AS Total_Sales_Weekly, CASE WHEN ROW_NUMBER() OVER (PARTITION BY ws.month_start_date ORDER BY ws.week_start_date) = 1 THEN cm.Monthly_Total_Orders ELSE NULL END AS Total_Orders_Current_Month, CASE WHEN ROW_NUMBER() OVER (PARTITION BY ws.month_start_date ORDER BY ws.week_start_date) = 1 THEN cm.Monthly_Total_Order_Quantity ELSE NULL END AS Total_Order_Quantity_Current_Month, CASE WHEN ROW_NUMBER() OVER (PARTITION BY ws.month_start_date ORDER BY ws.week_start_date) = 1 THEN cm.Monthly_Total_Sales ELSE NULL END AS Total_Sales_Current_Month, CASE WHEN ROW_NUMBER() OVER (PARTITION BY ws.month_start_date ORDER BY ws.week_start_date) = 1 THEN ly.Yearly_Total_Orders ELSE NULL END AS Total_Orders_Last_Year, CASE WHEN ROW_NUMBER() OVER (PARTITION BY ws.month_start_date ORDER BY ws.week_start_date) = 1 THEN ly.Yearly_Total_Order_Quantity ELSE NULL END AS Total_Order_Quantity_Last_Year, CASE WHEN ROW_NUMBER() OVER (PARTITION BY ws.month_start_date ORDER BY ws.week_start_date) = 1 THEN ly.Yearly_Total_Sales ELSE NULL END AS Total_Sales_Last_Year, CASE WHEN ROW_NUMBER() OVER (PARTITION BY ws.month_start_date ORDER BY ws.week_start_date) = 1 THEN lm.Monthly_Total_Orders ELSE NULL END AS Total_Orders_Last_Month, CASE WHEN ROW_NUMBER() OVER (PARTITION BY ws.month_start_date ORDER BY ws.week_start_date) = 1 THEN lm.Monthly_Total_Order_Quantity ELSE NULL END AS Total_Order_Quantity_Last_Month, CASE WHEN ROW_NUMBER() OVER (PARTITION BY ws.month_start_date ORDER BY ws.week_start_date) = 1 THEN lm.Monthly_Total_Sales ELSE NULL END AS Total_Sales_Last_Month, lw.Weekly_Total_Orders AS Total_Orders_Last_Week, lw.Weekly_Total_Order_Quantity AS Total_Order_Quantity_Last_Week, lw.Weekly_Total_Sales AS Total_Sales_Last_Week FROM weekly_summary ws LEFT JOIN monthly_aggregates cm ON ws.month_start_date = cm.month_start_date LEFT JOIN yearly_aggregates ly ON ws.year_start_date = ly.year_start_date LEFT JOIN monthly_aggregates lm ON DATE_SUB(ws.month_start_date, INTERVAL 1 MONTH) = lm.month_start_date LEFT JOIN weekly_summary lw ON DATE_SUB(ws.week_start_date, INTERVAL 1 WEEK) = lw.week_start_date ORDER BY ws.week_start_date DESC;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            